// ===== GENERATOR HELPERS =====
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function gradeLevel(gr){return(gr==='ט'||gr==='י')?'young':'mature'}
function getGenInputs(){
  var d=document.getElementById('genDim').value,gr=document.getElementById('genGrade').value,t=document.getElementById('genTopic').value.trim(),inp=document.getElementById('genTopic');
  if(!t){inp.style.border='2px solid #C0605A';inp.placeholder='חובה — כתבי נושא';return null}
  inp.style.border='';
  var et=esc(t);
  return{dim:d,grade:gr,topic:et,rawTopic:t,dimName:DIMS[d].name,dimColor:DIMS[d].color,skill:DIMS[d].skill,level:gradeLevel(gr),content:GEN_CONTENT[d]}
}
function openGenWindow(h){var w=window.open('','_blank');if(!w){alert('הדפדפן חסם את החלון — אפשרו חלונות קופצים');return}w.document.write(h);w.document.close()}
function pick(arr){return arr[Math.floor(Math.random()*arr.length)]}

