function genBaseCSS(color){return '*{margin:0;padding:0;box-sizing:border-box}body{font-family:Heebo,sans-serif;background:#F5F0E8;min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px}h2{font-size:1.6rem;font-weight:800;color:#4A3F35;margin-bottom:16px}.ctn{max-width:800px;width:100%;text-align:center}.bdg{display:inline-block;padding:6px 18px;border-radius:20px;font-size:.85rem;font-weight:600;background:'+color+'22;color:'+color+';margin-bottom:12px}h1{font-size:2.2rem;font-weight:800;color:#4A3F35;margin-bottom:8px}.sub{font-size:1rem;color:#6B5F55;margin-bottom:40px}.aa{display:none;background:#FFFDF8;border-radius:20px;padding:40px;border:2px solid #E8DDD0;margin-top:24px;animation:fu .4s ease;position:relative}.aa::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:'+color+';border-radius:20px 20px 0 0}.aa.sh{display:block}@keyframes fu{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}@keyframes pop{from{transform:scale(0)}to{transform:scale(1)}}.back-btn{position:fixed;top:16px;right:16px;padding:10px 20px;background:#FFFDF8;border:2px solid #E8DDD0;border-radius:12px;font-family:Heebo;font-weight:600;cursor:pointer;font-size:.85rem;z-index:100;min-height:44px}button{min-height:44px}'}

